# such that p is far from all pillars in S.

def find_skippable_points(n):
    grid = [(x, y) for x in range(n) for y in range(n)]
    def is_valid(S):
        if len(S) < 2: return False
        for i in range(len(S)):
            for j in range(i + 1, len(S)):
                p1 = S[i]
                p2 = S[j]
                if max(abs(p1[0] - p2[0]), abs(p1[1] - p2[1])) < 2:
                    return False
        return True

    skippable = []
    for p in grid:
        # Can we find a valid set S of size >= 2 such that p is far from all pillars in S?
        # This is equivalent to: is there a valid set S in the set of points far from p?
        far_points = [q for q in grid if max(abs(q[0] - p[0]), abs(q[1] - p[1])) >= 2]

        found_S = False
        # Check all subsets of far_points
        for r in range(2, len(far_points) + 1):
            for combo in itertools.combinations(far_points, r):
                if is_valid(combo):
                    found_S = True
                    break
            if found_S: break

        if not found_S:
            skippable.append(p)
    return skippable

